// exec updates the rows and their edges, in one transaction, and returns how
// many there were.
pub fn (b ArticleUpdate) exec() !int {
	return b.graph.client.update(b.data)
}

// ArticleDeleteOne builds the delete of one `articles` row. Start one with
// `Graph.articles().delete_one(node)` or `delete_one_id(id)`.
pub struct ArticleDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q ArticleQuery) delete_one(node ArticleNode) ArticleDeleteOne {
	return q.delete_one_id(node.article.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q ArticleQuery) delete_one_id(id int) ArticleDeleteOne {
	return ArticleDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete_one
			table: 'articles'
			key:   id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b ArticleDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'articles'
		}
	}
}

// ArticleDelete builds the delete of the `articles` rows that match its conditions.
// Start one with `Graph.articles().delete()`.
pub struct ArticleDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q ArticleQuery) delete() ArticleDelete {
	return ArticleDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'articles'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b ArticleDelete) where(conds ...load.Cond) ArticleDelete {
	return ArticleDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

